  /* ---------- 里程量算（haversine，km） ---------- */
  function dist(a, b) {
    var rad = Math.PI / 180, R = 6371;
    var dLat = (b[1]-a[1])*rad, dLng = (b[0]-a[0])*rad;
    var s = Math.sin(dLat/2)**2 + Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin(dLng/2)**2;
    return 2 * R * Math.asin(Math.sqrt(s));
  }
  function chainLength(fc) {
    var total = 0;
    fc.features.forEach(function (f) {
      var c = f.geometry.coordinates;
      for (var i = 1; i < c.length; i++) total += dist(c[i-1], c[i]);
    });
    return total;
  }

